mapper.select:
SELECT t.*, c.category_name, cu.real_name AS creator_name, au.real_name AS assignee_name FROM ticket t LEFT JOIN ticket_category c ON c.id = t.category_id LEFT JOIN `user` cu ON cu.id = t.creator_id LEFT JOIN `user` au ON au.id = t.assignee_id WHERE t.deleted = 0 AND t.status = #{status} AND t.priority = #{priority} AND t.category_id = #{categoryId} AND t.creator_id = #{creatorId} AND t.assignee_id IS NULL AND t.assignee_id = #{assigneeId}
AND (t.ticket_no LIKE CONCAT('%', #{keyword}, '%') OR t.title LIKE CONCAT('%', #{keyword}, '%') OR t.content LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY t.update_time DESC, t.id DESC
